/*
 * A247813  Numbers in decimal representation with distinct digits, such that
 *          in Spanish their digits are in alphabetic order.
 * https://oeis.org/A247813
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, word, fini, full
 * Formula:   not stated
 * Range:     u8 n <= 2, u16 n <= 130, u32 n <= 512, u64 n <= 512,
 *            u128 n <= 512, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by enumerating all numbers with distinct digits, 
   sorting the digits by their Spanish names and then sorting 
   the resulting numbers numerically. */
#include <stdlib.h>

/* Comparator for qsort to work with any seq_t type */
static int compare_seq(const void *p1, const void *p2)
{
    const seq_t *a = (const seq_t *)p1;
    const seq_t *b = (const seq_t *)p2;
    return (*a < *b) ? -1 : (*a > *b);
}

seq_t a(idx_t n)
{
    /* one‑time cache construction */
    static seq_t cache[512];
    static int initialized = 0;

    if (!initialized) {
        initialized = 1;

        /* Order of digits according to the Spanish names of the digits */
        const int order[9] = {5, 4, 2, 9, 8, 6, 7, 3, 1};

        /* single‐digit zero, the first term of the sequence */
        cache[0] = (seq_t)0;

        /* generate all numbers from non‑empty subsets of {1,…,9} */
        idx_t pos = 1;
        const idx_t limit = ((idx_t)1 << 9); /* 512 values total */
        for (idx_t mask = 1; mask < limit; ++mask) {
            uint64_t val = 0;           /* intermediate type large enough */
            for (int i = 0; i < 9; ++i) {
                if (mask & ((idx_t)1 << i))
                    val = val * 10 + (uint64_t)order[i];
            }
            cache[pos++] = (seq_t)val; /* cast to seq_t (may truncate if needed) */
        }

        /* sort the resulting numbers numerically */
        qsort(cache, limit, sizeof(seq_t), compare_seq);
    }

    /* offset 1: a(1) = 0 */
    if (n == 0 || n > 512)
        return (seq_t)0;          /* undefined for n<1 or out of range */
    return cache[n - 1];
}
